const menu=document.querySelector('.menu-btn'),nav=document.querySelector('.nav-links');if(menu)menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open)});document.querySelectorAll('.nav-links a').forEach(a=>a.addEventListener('click',()=>nav?.classList.remove('open')));
const slides=[...document.querySelectorAll('.slide')],dots=[...document.querySelectorAll('.carousel-dots button')];let current=0,timer;function show(i){if(!slides.length)return;current=(i+slides.length)%slides.length;slides.forEach((s,n)=>s.classList.toggle('active',n===current));dots.forEach((d,n)=>d.classList.toggle('active',n===current));clearInterval(timer);timer=setInterval(()=>show(current+1),6000)}dots.forEach((d,i)=>d.addEventListener('click',()=>show(i)));document.querySelector('[data-next]')?.addEventListener('click',()=>show(current+1));document.querySelector('[data-prev]')?.addEventListener('click',()=>show(current-1));if(slides.length)show(0);
document.querySelector('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();e.currentTarget.reset();document.querySelector('.form-status').style.display='block'});
